home.code:
// Edítame y pulsa Ejecutar.
world 1-1 {
  coin monedas = 0
  run i from 1 to 5 {
    power_up monedas by 10
    wahoo("Bloque ", i, ": ", monedas, " monedas")
  }
  question monedas >= 50 {
    wahoo("¡1-UP!")
  }
}

