opt.code:
pipe segundos(minutos: coins) -> coins {
  flag minutos * 60
}

world 1-1 {
  coin tiempo = 2 * 60 + 30
  question 1 < 2 {
    wahoo("Tiempo: ", tiempo + 0)
  } else {
    wahoo("nunca se ve")
  }
  bounce goomba {
    wahoo("nunca se ejecuta")
  }
  wahoo(segundos(3) * 1)
}
